190→        let info = UpdateInfo {
191→            current: "0.1.0".to_string(),
192→            latest: "0.2.0".to_string(),
193→            update_available: true,
194→            release_url: None,
195→            checked_at: Utc::now(),
196→        };
197→        let method = InstallMethod::Unknown;
198→
199→        let result = prompt_for_update(&mut ui, &info, &method).unwrap();
