import re, os

results = []
for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            content = fh.read()

        # Find #[cfg(test)] and note the line number
        lines = content.split('\n')
        test_start = None
        for i, line in enumerate(lines):
            if '#[cfg(test)]' in line:
                test_start = i
                break

        # Only look at lines before #[cfg(test)]
        if test_start is not None:
            check_lines = lines[:test_start]
        else:
            check_lines = lines

        for i, line in enumerate(check_lines):
            if '.unwrap()' in line and '///' not in line and '//!' not in line and '//' not in line.split('.unwrap()')[0].split('//')[-1] if '//' in line.split('.unwrap()')[0] else True:
                # Filter out comments
                stripped = line.lstrip()
                if stripped.startswith('//'):
                    continue
                results.append(f'{path}:{i+1}: {line.rstrip()}')

for r in sorted(results):
    print(r)
PYEOF

