python3 << 'PYEOF'
import os

results = []
for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            lines = fh.readlines()

        # Find where #[cfg(test)] starts
        test_start = len(lines)  # default: all lines are production
        for i, line in enumerate(lines):
            if '#[cfg(test)]' in line:
                test_start = i
                break

        # Only check lines before #[cfg(test)]
        for i in range(test_start):
            line = lines[i]
            if '.unwrap()' not in line:
                continue
            stripped = line.lstrip()
            if stripped.startswith('//'):
                continue
            results.append(f'{path}:{i+1}: {stripped.rstrip()}')

for r in sorted(results):
    print(r)
PYEOF

