160→/// Inner loop for `prompt_yes_no`, split out so the caller can guarantee
161→/// cursor cleanup regardless of how the loop exits.
162→fn prompt_yes_no_loop(
163→    prompt: &Prompt,
164→    options: &[PromptOption],
165→    term: &Term,
166→    sel: &mut usize,
167→    pad: &str,
168→    active_prefix: &Style,
169→    active_style: &Style,
170→    inactive_prefix: &Style,
171→    inactive_style: &Style,
172→) -> Result<PromptResult> {
173→    loop {
174→        // Draw option lines
175→        for (i, opt) in options.iter().enumerate() {
176→            let line = if i == *sel {
177→                format!(
178→                    "{}{} {}",
179→                    pad,
180→                    active_prefix.apply_to("›"),
181→                    active_style.apply_to(&opt.label)
182→                )
183→            } else {
184→                format!(
185→                    "{}{} {}",
186→                    pad,
187→                    inactive_prefix.apply_to("·"),
188→                    inactive_style.apply_to(&opt.label)
189→                )
190→            };
191→            term.write_line(&line).map_err(BivvyError::Io)?;
192→        }
193→        term.flush().map_err(BivvyError::Io)?;
194→
195→        // Read key
196→        let key = term.read_key().map_err(BivvyError::Io)?;
197→
198→        let chosen = match key {
199→            Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
200→            Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
201→            Key::Enter | Key::Char(' ') => Some(*sel),
202→            Key::ArrowDown | Key::Tab | Key::Char('j') => {
203→                *sel = (*sel + 1) % options.len();
204→                None
205→            }
206→            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
207→                *sel = (*sel + options.len() - 1) % options.len();
208→                None
209→            }
210→            // Ctrl+D (EOT) — treat as EOF / user cancellation
211→            Key::Char('\x04') => {
212→                // Clear the rendered options before returning
213→                term.clear_last_lines(options.len()).ok();
214→                return Err(BivvyError::Io(std::io::Error::new(
215→                    std::io::ErrorKind::UnexpectedEof,
216→                    "EOF (Ctrl+D)",
217→                )));
218→            }
219→            _ => None,
220→        };
221→
222→        if let Some(idx) = chosen {
223→            // Clear option lines
224→            term.clear_last_lines(options.len())
225→                .map_err(BivvyError::Io)?;
226→            // Clear the prompt question line
227→            term.clear_last_lines(1).map_err(BivvyError::Io)?;
228→            // Re-print prompt with selection (show "yes" or "no")
229→            let answer_text = if options[idx].value == "yes" {
230→                "yes"
231→            } else {
232→                "no"
233→            };
234→            term.write_line(&format!(
235→                "{} {}",
236→                prompt.question,
237→                Style::new().bold().apply_to(answer_text)
238→            ))
239→            .map_err(BivvyError::Io)?;
240→
241→            return Ok(PromptResult::String(options[idx].value.clone()));
242→        }
243→
244→        // Clear option lines for redraw
245→        term.clear_last_lines(options.len())
246→            .map_err(BivvyError::Io)?;
247→    }
248→}
