250→fn prompt_multiselect(
251→    prompt: &Prompt,
252→    options: &[PromptOption],
253→    term: &Term,
254→) -> Result<PromptResult> {
255→    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();
256→
257→    let default_values: Vec<&str> = prompt
258→        .default
259→        .as_deref()
260→        .map(|d| d.split(',').collect())
261→        .unwrap_or_default();
262→    let defaults: Vec<bool> = options
263→        .iter()
264→        .map(|o| default_values.contains(&o.value.as_str()))
265→        .collect();
266→
267→    let selections = MultiSelect::with_theme(&prompt_theme())
268→        .with_prompt(&prompt.question)
269→        .items(&labels)
270→        .defaults(&defaults)
271→        .interact_on(term)
272→        .map_err(map_dialoguer_err)?;
273→
274→    let values: Vec<String> = selections
275→        .iter()
276→        .map(|&i| options[i].value.clone())
277→        .collect();
278→
279→    Ok(PromptResult::Strings(values))
280→}
